package net.civeira.phylax.feature.observe.viewer;

import java.util.Locale;

import io.quarkus.arc.DefaultBean;
import jakarta.enterprise.context.ApplicationScoped;

/**
 * Viewer page without themes: the fragment with the own styles of the viewer.
 */
@DefaultBean
@ApplicationScoped
public class StaticObservePage implements ObservePageGateway {

  @Override
  public String getFullPage(final String title, final String innerContent, final Locale locale,
      final String variant) {
    return ObservePages.standalone(title, innerContent,
        null == locale ? "en" : locale.getLanguage());
  }
}
